require __DIR__.'/includes/bootstrap.php';$buyer=require_login('buyer');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: /orders.php');exit;}verify_csrf();$id=filter_var($_POST['order_id']??null,FILTER_VALIDATE_INT);try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM orders WHERE id=? AND buyer_id=? AND status='new' FOR UPDATE");$q->execute([$id,$buyer['id']]);$o=$q->fetch();if(!$o)throw new RuntimeException('Only a new order request can be cancelled.');$pdo->prepare("UPDATE orders SET status='cancelled' WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE products SET quantity=quantity+?,status=IF(status='sold_out','active',status) WHERE id=?")->execute([$o['quantity'],$o['product_id']]);$pdo->commit();flash('Order request cancelled and quantity returned to the listing.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Could not cancel this request.','error');}header('Location: /orders.php');exit;
